def _day_of_week(y, m, d):
    t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
    if m < 3:
        y -= 1
    return (y + y // 4 - y // 100 + y // 400 + t[m - 1] + d) % 7


def last_weekday_on_or_before(year, month, day, weekday_num):
    sunday_based = _day_of_week(year, month, day)
    monday_based = (sunday_based + 6) % 7
    offset = (monday_based - weekday_num) % 7
    return day - offset

