def parse_duration_words(s):
    tokens = s.split(' ')
    total_minutes = 0
    index = 0
    while index < len(tokens):
        number = int(tokens[index])
        unit = tokens[index + 1]
        if unit.startswith('hour'):
            total_minutes += number * 60
        else:
            total_minutes += number
        index += 2
    return total_minutes

def count_valid_dates_in_list(date_list):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def is_valid(s):
        if not isinstance(s, str) or len(s) != 10:
            return False
        if s[4] != '-' or s[7] != '-':
            return False
        year_s, month_s, day_s = s[:4], s[5:7], s[8:10]
        if not (year_s.isdigit() and month_s.isdigit() and day_s.isdigit()):
            return False
        y, m, d = int(year_s), int(month_s), int(day_s)
        if not (1 <= m <= 12):
            return False
        month_lengths = [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return 1 <= d <= month_lengths[m - 1]
    return sum(1 for date_str in date_list if is_valid(date_str))

