def is_valid_non_blocked_email(s, blocked_domains):
    if s.count('@') != 1:
        return False
    local, domain = s.split('@')
    if not local:
        return False
    if not all(c.isalnum() or c in '._+-' for c in local):
        return False
    if '.' not in domain:
        return False
    for label in domain.split('.'):
        if not label or not all(c.isalnum() or c == '-' for c in label):
            return False
    return domain.lower() not in {d.lower() for d in blocked_domains}

