def is_valid_slug(s):
    if len(s) == 0:
        return False
    if s[0] == '-' or s[-1] == '-':
        return False
    if '--' in s:
        return False
    for c in s:
        if c.isdigit() or c == '-':
            continue
        if c.isalpha() and c.islower():
            continue
        return False
    return True
